  "$schema": "http://json-schema.org/draft-04/schema#",
  "title": "Fluid for cubic EOS in CoolProp",
  "items": {
    "properties": {
      "name": {
        "description": "Name of the fluid",
        "type": "string"
      },
      "CAS": {
        "description": "CAS registry number of the fluid",
        "type": "string"
      },
      "Tc": {
        "description": "Critical temperature (K)",
        "type": "number",
        "minimum": 0.1,
        "maximum": 20000
      },
      "pc": {
        "description": "Critical pressure (Pa)",
        "type": "number",
        "minimum": 0,
        "maximum": 500000000
      },
      "rhomolarc": {
        "description": "Critical density (mol/m^3)",
        "type": "number",
        "minimum": 0.1,
        "maximum": 2000000
      },
      "rhomolarc_units": {
        "description": "Units of the critical density provided",
        "enum": [
          "mol/m^3",
          "kg/m^3"
        ]
      },
      "acentric": {
        "description": "Acentric factor (-)",
        "type": "number",
        "minimum": -10,
        "maximum": 10
      },
      "molemass": {
        "description": "Molar mass (kg/mol)",
        "type": "number",
        "minimum": 0,
        "maximum": 1
      },
      "molemass_units": {
        "description": "Units of the molar mass provided",
        "enum": [
          "kg/mol"
        ]
      },
      "pc_units": {
        "description": "Units of the critical pressure",
        "enum": [
          "Pa"
        ]
      },
      "Tc_units": {
        "description": "Units of the critical temperature",
        "enum": [
          "K"
        ]
      },
      "aliases": {
        "type": "array",
        "items": {
          "type": "string"
        },
        "minItems": 0
      },
      "alpha": {
        "description": "The alpha function being used",
        "properties": {
          "type": {
            "enum": [
              "Twu",
              "Mathias-Copeman",
              "default"
            ]
          },
          "c": {
            "type": "array",
            "items": {
              "type": "number"
            },
            "minItems": 3,
            "maxItems": 3
          }
        }
      }
    },
    "required": [
      "name",
      "CAS",
      "Tc",
      "Tc_units",
      "pc",
      "pc_units",
      "acentric",
      "molemass",
      "molemass_units"
    ]
  },
  "type": "array"
}

